INSERT INTO public."LegalTemplate" (id, title, notice_type, body, is_active, created_at) VALUES ('270c1f81-dba3-401c-bd5b-03aa6cb515a7', '14-Day Notice of Non-Payment of Rent', 'notice_14day', 'FOURTEEN DAY NOTICE OF NONPAYMENT OF RENT\n\nTO: {{full_legal_name}}\n    {{tenant_address}}\n\n    Case No.: {{case_number}}\n\nDate: {{notice_date}}\n\nPLEASE TAKE NOTICE that you are indebted to {{landlord_entity}}, as Landlord/Owner, for the rent of the premises known as:\n\n    {{unit_address}}\n\nin the amount of {{outstanding_balance}}, for the rental period from {{period_start}} through {{period_end}}, at the agreed monthly rental of {{monthly_rent}}.\n\nPLEASE TAKE FURTHER NOTICE that demand is hereby made that you pay said sum within FOURTEEN (14) DAYS after service of this Notice upon you, or surrender up possession of said premises; and that upon your failure to do so, the Landlord/Owner will commence summary proceedings to recover possession of said premises and all rents due and owing.\n\nDated: {{notice_date}}\n\n{{landlord_entity}}\n\nBy: ___________________________\n    {{landlord_signatory}}\n    {{landlord_address}}\n    Tel: {{landlord_phone}}\n    Email: {{landlord_email}}', true, '2026-06-24 08:47:11.735');
INSERT INTO public."LegalTemplate" (id, title, notice_type, body, is_active, created_at) VALUES ('28eb2b7a-7b90-41ce-8a8d-7b71d38fc23e', '90-Day Termination Notice (8607 — 101st St)', 'notice_90day_8607', '90-Day NOTICE OF TERMINATION OF TENANCY
INSERT INTO public."LegalTemplate" (id, title, notice_type, body, is_active, created_at) VALUES ('59f862f6-2708-4a05-82f8-863284528cea', '90-Day Termination Notice (B84 — Beach 84th St)', 'notice_90day_b84', '90-Day NOTICE OF TERMINATION OF TENANCY
INSERT INTO public."LegalTemplate" (id, title, notice_type, body, is_active, created_at) VALUES ('7eebed0b-84e2-4816-b57f-ac69ea857860', '5-Day Notice of Non-Payment of Rent', 'notice_5day', 'FIVE DAY NOTICE OF NONPAYMENT OF RENT
INSERT INTO public."LegalTemplate" (id, title, notice_type, body, is_active, created_at) VALUES ('81ac1827-03f2-4982-8272-1b041ecc375f', '7-Day Notice of Non-Payment of Rent', 'notice_7day', 'SEVEN DAY NOTICE OF NONPAYMENT OF RENT\n\nTO: {{full_legal_name}}\n    {{tenant_address}}\n\n    Case No.: {{case_number}}\n\nDate: {{notice_date}}\n\nPLEASE TAKE NOTICE that you are indebted to {{landlord_entity}}, as Landlord/Owner, for the rent of the premises known as:\n\n    {{unit_address}}\n\nin the amount of {{outstanding_balance}}, for the rental period from {{period_start}} through {{period_end}}, at the agreed monthly rental of {{monthly_rent}}.\n\nPLEASE TAKE FURTHER NOTICE that demand is hereby made that you pay said sum within SEVEN (7) DAYS after service of this Notice upon you, or surrender up possession of said premises; and that upon your failure to do so, the Landlord/Owner will commence summary proceedings to recover possession of said premises and all rents due and owing.\n\nDated: {{notice_date}}\n\n{{landlord_entity}}\n\nBy: ___________________________\n    {{landlord_signatory}}\n    {{landlord_address}}\n    Tel: {{landlord_phone}}\n    Email: {{landlord_email}}', true, '2026-06-24 08:47:11.735');
